/**
 * A schedule: `schedule` is a five-field cron expression in UTC.
 *
 * `enabled: false` pauses the trigger and keeps its definition: the schedule
 * stops firing while the agent stays live for on-demand starts and open
 * sessions keep taking follow-ups (`ellipsis.enabled: false` pauses the
 * whole file instead). Re-enabling resumes at the next scheduled time; runs
 * missed while paused are not made up.
 */
export interface CronTrigger {
  enabled: boolean;
  schedule: string;
  type: 'cron';
}
/**
 * An event trigger: exactly one surface block names the events to match.
 *
 * `enabled: false` pauses the trigger and keeps its definition: events stop
 * matching while the agent stays live for on-demand starts and open
 * sessions keep taking follow-ups (`ellipsis.enabled: false` pauses the
 * whole file instead).
 */
