/**
 * Environment compute sizing. Every field is optional; an omitted field
 * inherits the platform default (2 vCPU / 4096 MiB / 3600s). A resolved value
 * outside the platform bounds fails validation loudly (a sync error on the
 * config) rather than being clamped silently.
 *
 * `memory` and `timeout` each accept a shorthand string ("8GB", "30m") or an
 * explicit units object ({gb: 8}, {minutes: 30}); the `memory_mib` /
 * `timeout_seconds` properties resolve either form to the canonical integer
 * the environment is sized with.
 *
 * `timeout` is the max wall-clock the agent may run in one environment before
 * it is stopped, capped at 1h (equal to the default, so today the knob only
 * shortens a session; the cap matches the 1-hour validity of the session's
 * GitHub token).
 *
 * Compute currently uses a temporary flat one-cent amount each time an
 * environment is started for a session, subject to the account's existing
 * free-compute exemptions.
 */
export interface ComputeConfig1 {
  cpu: number | null;
  memory: string | MemorySize | null;
  timeout: string | Duration | null;
}
/**
 * Environment lifecycle scripts, in order: build_base, after_checkout,
 * before_start. The first two produce reusable snapshots; before_start runs
 * before an agent starts or resumes its session. Scripts run as the environment's
 * user in the workspace directory `/sandbox`. A nonzero exit fails the session.
 *
 * Legacy post_start/post_clone scripts remain supported for existing configs;
 * both run after workspace preparation, before the agent starts or resumes.
 * They cannot be combined with the new lifecycle fields.
 */
export interface EnvironmentHooks1 {
  /**
   * Prepare the requested source revision after Ellipsis checks out all repositories, before saving the prepared environment. Skipped when that prepared environment is reused.
   */
  after_checkout: EnvironmentScript | string | null;
  /**
   * Run before the agent starts or resumes a session, after the environment is ready. This hook is not cached and adds to session startup time.
   */
  before_start: EnvironmentScript | string | null;
  /**
   * Build a reusable environment before full checkout. Cached by declared inputs, script, toolchain, resources, and build configuration. A string is shorthand for run with all repositories as inputs.
   */
  build_base: EnvironmentBaseBuild | string | null;
  /**
   * Legacy session startup script. Use before_start for session setup or after_checkout for cached source preparation.
   */
  post_clone: string | null;
  /**
   * Legacy session startup script. Use before_start in new configurations.
   */
  post_start: string | null;
}
